import {syntheticProductRun,referenceMinimum} from './platinum-rules.mjs';
const $=id=>document.getElementById(id),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
function render(){
 const future=$('version').value==='future',active=$('active').value==='true',grace=$('grace').value;
 const r=syntheticProductRun({future,active,grace});$('active').disabled=future;
 $('setting-note').textContent=future?'For this standard-account example, the future policy enforces active regardless of the old selection.':'The setting applies at transaction time and closing for this reference case.';
 $('pif').textContent=money(r.moved.pifRemaining);$('pot').textContent=money(r.moved.potBalance);
 $('interest').textContent=r.interest.interest===null?'Unknown':money(r.interest.interest);
 $('interest-status').textContent=r.interest.status==='blocked_missing_grace_history'?'Missing grace evidence':grace==='eligible'?'Conditional on qualifying history':'Rounded DPR + daily compounding';
 $('minimum').textContent=r.interest.interest===null?'Unknown':money(referenceMinimum({pif:r.moved.pifRemaining,potAndCash:r.moved.potBalance+r.interest.interest,interest:r.interest.interest}).total);
 $('flow').innerHTML=`<article><h3>1 · Route the purchase</h3><p>${money(r.routed.pif)} to Pay In Full; ${money(r.routed.pot)} to Pay Over Time. The entire purchase exceeds available revolving capacity.</p></article><article><h3>2 · Allocate the payment</h3><p>${money(r.paid.allocations.pif)} to billed Pay In Full; ${money(r.paid.allocations.pot)} to Pay Over Time. New unbilled Pay In Full is kept distinct from the billed amount due.</p></article><article><h3>3 · Reclassify at close</h3><p>${money(r.moved.moved)} moves to Pay Over Time. Total principal remains ${money(r.principalClosing)}. Transferred principal starts interest the next day.</p></article>`;
 const points=Array.from({length:30},(_,i)=>{const d=i+1;let pif=15000+(d>=5?r.routed.pif:0)-(d>=10?r.paid.allocations.pif:0),pot=90000+(d>=5?r.routed.pot:0)-(d>=10?r.paid.allocations.pot:0);if(d===30){pif-=r.moved.moved;pot+=r.moved.moved;}return {d,pif,pot,total:pif+pot};});
 const w=900,h=280,x=d=>70+(d-1)/29*800,y=n=>240-n/150000*210;
 const line=key=>points.map((p,i)=>`${i?'L':'M'}${x(p.d)},${y(p[key])}`).join(' ');
 $('lab-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Synthetic daily principal: Pay In Full, Pay Over Time and account total"><title>Synthetic balance classification across a month</title>${[0,50000,100000,150000].map(n=>`<line x1="70" y1="${y(n)}" x2="870" y2="${y(n)}" stroke="#d3dfd0"/><text x="60" y="${y(n)+5}" text-anchor="end">${money(n)}</text>`).join('')}${[['total','#193e2b'],['pot','#216a9b'],['pif','#986224']].map(([k,c])=>`<path d="${line(k)}" stroke="${c}" stroke-width="3" fill="none"/>`).join('')}${[1,5,10,20,30].map(d=>`<text x="${x(d)}" y="268" text-anchor="middle">Day ${d}</text>`).join('')}</svg><p class="caption">● Total principal (green) · Pay Over Time (blue) · Pay In Full (brown). Values appear in the table below.</p>`;
 $('precision').textContent=r.interest.interest===null?'Interest and a complete closing amount are blocked until grace evidence is supplied. Principal classification can still be explored.':`DPR ${r.interest.dprPercent.toFixed(4)}% per day. ${r.interest.precision}. No cash advances or plans in this synthetic run.`;
 $('daily').innerHTML=`<table><thead><tr><th>Day</th><th>Pay In Full principal</th><th>Pay Over Time principal</th><th>Total principal</th><th>Unbilled purchase interest</th></tr></thead><tbody>${points.map(p=>`<tr><td>${p.d}</td><td class="amount">${money(p.pif)}</td><td class="amount">${money(p.pot)}</td><td class="amount">${money(p.total)}</td><td class="amount">${r.interest.days.length?money(r.interest.days[p.d-1].unbilledInterest):'Unknown'}</td></tr>`).join('')}</tbody></table>`;
}
for(const id of ['version','active','grace'])$(id).onchange=render;render();
